// Arma lo que muestra la tarjeta con el pronostico de Colab
// y el modo del nodo (llega por el topico de datos)
var clases = ['BAJO', 'MEDIO', 'ALTO'];
var colores = ['#2ECC40', '#FFDC00', '#FF4136'];
var modos = { auto: 'AUTOMATICO', manual: 'MANUAL', ia: 'IA' };
var quien = { reglas: 'las reglas', manual: 'el usuario', ia: 'la IA',
              respaldo: 'las reglas (sin IA)', seguridad: 'seguridad (mas de 250 cm)' };

// Tarjeta sin pronostico (al iniciar o 5 s sin datos de la IA)
function sinIA(nodo) {
    var nota = 'Esperando a la IA: ejecuta la seccion 9 del cuaderno de Colab';
    if (nodo.modo === 'ia') {
        nota = 'Modo IA sin pronostico: deciden las reglas. Revisa el cuaderno de Colab';
    }
    return { payload: { texto: 'Esperando', color: '#A3B18A', bajo: 0, medio: 0, alto: 0,
                        nota: nota, anticipa: false, linea: lineaModo(nodo) } };
}
function lineaModo(nodo) {
    return 'Nodo en modo ' + (modos[nodo.modo] || nodo.modo) + ' · decide ' + (quien[nodo.decide] || nodo.decide);
}

var nodo = context.get('nodo') || { modo: 'auto', decide: 'reglas' };

// Lectura del nodo: solo se guarda el modo y quien decide
if (msg.topic === 'ucol-eq1/rio/nodo1/datos') {
    var d = msg.payload;
    if (typeof d !== 'object' || d === null) {
        return null;
    }
    var nuevo = { modo: d.modo || 'auto', decide: d.decide || (d.modo === 'manual' ? 'manual' : 'reglas') };
    var cambio = nuevo.modo !== nodo.modo || nuevo.decide !== nodo.decide;
    context.set('nodo', nuevo);
    // Si no hay IA, la tarjeta se actualiza aqui; si hay, con el siguiente pronostico
    if (cambio && context.get('sinIA') !== false) {
        return sinIA(nuevo);
    }
    return null;
}

if (msg.payload.sinDatos) {
    context.set('sinIA', true);
    return sinIA(nodo);
}

// Pronostico de Colab
context.set('sinIA', false);
var p = msg.payload.prob || [0, 0, 0];
var r = msg.payload.riesgo_15s;
var anticipa = r > msg.payload.riesgo_ahora;
var nota = msg.payload.modelo + ' solo avisa (el nodo no esta en modo IA)';
if (nodo.modo === 'ia') {
    nota = msg.payload.modelo + ' decide el LED, el buzzer y la compuerta';
}
if (anticipa) {
    nota = 'Alerta anticipada: ahora es ' + clases[msg.payload.riesgo_ahora] + ' y la IA espera ' + clases[r];
}
msg.payload = {
    texto: clases[r],
    color: colores[r],
    bajo: Math.round(p[0] * 100),
    medio: Math.round(p[1] * 100),
    alto: Math.round(p[2] * 100),
    nota: nota,
    anticipa: anticipa,
    linea: lineaModo(nodo)
};
return msg;
